SELECT s.*, u.nick_name AS student_name, u.user_name AS student_number
FROM biz_data_lab_submission s
LEFT JOIN sys_user u ON u.user_id = s.student_id
WHERE s.student_id = #{studentId}
  AND s.question_id = #{questionId}
  AND s.source_type = #{sourceType}


      AND s.source_id = #{sourceId}


      AND s.source_id IS NULL

SELECT s.*, u.nick_name AS student_name, u.user_name AS student_number
FROM biz_data_lab_submission s
LEFT JOIN sys_user u ON u.user_id = s.student_id
JOIN biz_student st ON st.user_id=u.user_id
WHERE s.question_id = #{questionId}
  AND u.dept_id=#{deptId}

    AND EXISTS (SELECT 1 FROM biz_teacher_class tc WHERE tc.user_id=#{teacherId} AND tc.dept_id=u.dept_id
      AND CAST(tc.entry_year AS BINARY)=CAST(st.entry_year AS BINARY) AND CAST(tc.class_code AS BINARY)=CAST(st.class_code AS BINARY))

  AND s.source_type = #{sourceType}


      AND s.source_id = #{sourceId}


      AND s.source_id IS NULL


ORDER BY s.submitted_at DESC
